UPDATE services_content SET draft_json = '{"name":"אוטומציות עסקיות","short":"אוטומציות","lead":"הרובוט שעובד בשבילכם 24/7.","pain":"מפסיקים לעבוד כמו מכונות. אנחנו מחברים את כל הכלים שלכם יחד כדי שהעבודה השחורה והרוטינית תרוץ לבד ברקע, בזמן שאתם מתרכזים בקבלת החלטות גדולות.","points":["חשבוניות, אישורים ותיאומים על אוטומט","אתם קובעים את הכללים, הרובוט מבצע","מה שדורש את המוח והלב שלכם מגיע אליכם"],"h1a":"אל תעבדו בשביל המערכות.","h1b":"שהן יעבדו בשבילכם.","pageLead":"משימות שחוזרות על עצמן הן בזבוז זמן יקר שלכם ושל העובדים שלכם. אנחנו מחברים את כל הכלים שלכם כדי שהעבודה השחורה תתבצע מעצמה.","symptomsTitle":"איפה זה עוזר הכי הרבה","symptoms":["להעתיק פרטים ממערכת אחת לשנייה, כל יום מחדש","לשלוח הודעת אישור או מעקב אחרי כל פנייה","תזכורות שתלויות בזה שמישהו יזכור","לעדכן טבלאות ורשימות ביד"],"buildTitle":"איך זה עובד","build":[{"t":"ניקוי משימות סיזיפיות","d":"שליחת חשבוניות, הודעות אישור, תיאום פגישות ביומן: הכל קורה על אוטומט."},{"t":"חוקים קשוחים מראש","d":"אתם מגדירים את הכללים המקצועיים, הרובוט מבצע בדייקנות וללא טעויות."},{"t":"התערבות אנושית רק כשצריך","d":"מה שדורש את המוח והלב שלכם מגיע אליכם למסך; כל השאר פשוט רץ לבד."},{"t":"וכשצריך אתכם","d":"התהליך עוצר ומגיע למסך שלכם, במקום להמשיך לרוץ לבד."}],"closing":"בואו נראה מה אפשר להפוך לאוטומטי","closingBody":"ספרו לנו מה חוזר על עצמו אצלכם כל שבוע. נגיד בכנות מה שווה להפוך לאוטומטי, ומה עדיף להשאיר ידני.","note":"הדוגמאות כאן ממחישות את העיקרון. מה בדיוק ירוץ אוטומטית אצלכם ייקבע באפיון.","seo":{"title":"אוטומציות עסקיות | LAHAV AI","description":"מעבירים את הפעולות שחוזרות על עצמן למערכת שעושה אותן לבד, ומשאירים לכם את ההחלטות.","ogTitle":"אוטומציות עסקיות | LAHAV AI","ogDescription":"מעבירים את הפעולות שחוזרות על עצמן למערכת שעושה אותן לבד, ומשאירים לכם את ההחלטות.","ogImage":"","noindex":false}}', published_json = '{"name":"אוטומציות עסקיות","short":"אוטומציות","lead":"הרובוט שעובד בשבילכם 24/7.","pain":"מפסיקים לעבוד כמו מכונות. אנחנו מחברים את כל הכלים שלכם יחד כדי שהעבודה השחורה והרוטינית תרוץ לבד ברקע